Function biggest <- Greater(a As Integer, b As Integer)
  Define biggest As Integer <- a;
  If b > a Then
    biggest <- b;
  EndIf
EndFunction

Function accumulated <- Reduce(v As Vector<Integer>, f As Function(Integer, Integer) As Integer, initial As Integer)
  Define accumulated As Integer <- initial;
  For Each item In v Do
    accumulated <- f(accumulated, item);
  EndFor
EndFunction

Algorithm Maximum
  Define numbers As Vector<Integer> <- vector();
  Define number As Integer;
  Read number;
  While number <> 0 Do
    numbers.append(number);
    Read number;
  EndWhile
  If numbers.length() = 0 Then
    Write "No numbers";
  Else
    Write Reduce(numbers, Greater, numbers[0]);
  EndIf
EndAlgorithm
